const rows = $json.rows || [];
if (!Array.isArray(rows) || rows.length === 0) return [];
const meta = { complaint:{i:'🔴',n:'Жалобы'}, tech:{i:'⚙️',n:'Технические сбои'}, suggestion:{i:'💡',n:'Пожелания'}, other:{i:'💬',n:'Прочее'} };
const order = ['complaint','tech','suggestion','other'];
const esc = s => String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const byCat = {}; const ids = [];
for (const r of rows) { const c = meta[r.category]?r.category:'other'; (byCat[c]=byCat[c]||[]).push(r); ids.push(r.id); }
let out = '📋 <b>Обращения в поддержку за сутки</b> (всего ' + rows.length + ')\n';
for (const c of order) { const list = byCat[c]; if (!list || !list.length) continue; out += '\n' + meta[c].i + ' <b>' + meta[c].n + ' (' + list.length + '):</b>\n'; for (const r of list) { const who = esc(r.first_name||'Клиент') + (r.username ? ' (@'+esc(r.username)+')' : ''); let t = esc(r.text); if (t.length > 300) t = t.slice(0,300) + '…'; out += '• <b>' + who + ':</b> ' + t + '\n'; } }
return [{ json: { text: out, ids: ids } }];
